module drafts.crc32
export { fn crc32 }
fn crc32(bytes: ByteView) -> U64 {
  var crc = 0xffffffff
  var index = 0
  while index < byte_len(bytes) {
    let bit = byte_at(bytes, index) ^ crc
    crc = (crc >> 1) ^ bit
    index = index + 1
  }
  crc
}

module drafts.word_counter
export { fn count_words }
fn count_words(bytes: ByteView) -> U64 {
  var index = 0
  var words = 0
  var in_word = false
  while index < byte_len(bytes) {
    let byte = byte_at(bytes, index)
    if byte == 32 || byte == 9 { in_word = false } else { if !in_word { words = words + 1 } in_word = true }
    index = index + 1
  }
  words
}
